classdef Demos
%DEMOS Interactive demonstrations for MATLABX plot renderers.
%
% Each demo opens a uifigure with plot controls in a fixed-width accordion
% and a PlotAxes display. The returned handles remain available for command-
% line inspection:
%
%   [fig,host,renderer] = matlabx.ui.axes.plot.Demos.scatter();
%   [fig,host,renderer] = matlabx.ui.axes.plot.Demos.violin();
%
% See also matlabx.ui.axes.PlotAxes,
% matlabx.ui.axes.plot.ScatterRenderer,
% matlabx.ui.axes.plot.ViolinRenderer

% matlabx - MATLAB utilities for app building, image display, and analysis.
% Copyright (C) 2026 William Dean
%
% This program is free software; you can redistribute it and/or modify it
% under the terms of the GNU General Public License as published by the Free
% Software Foundation; either version 2 of the License, or (at your option)
% any later version.
%
% This program is distributed in the hope that it will be useful, but WITHOUT
% ANY WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS
% FOR A PARTICULAR PURPOSE. See the GNU General Public License for more
% details.
%
% You should have received a copy of the GNU General Public License along
% with this program; if not, see <https://www.gnu.org/licenses/>.

    methods (Static)

        function [fig,host,renderer] = scatter()
        %SCATTER Open an interactive ScatterRenderer demonstration.
            [fig,accordion,host] = matlabx.ui.axes.plot.Demos.createShell( ...
                "Scatter demo");
            renderer = matlabx.ui.axes.plot.ScatterRenderer;
            host.mount(renderer);

            dataPane = matlabx.ui.axes.plot.Demos.addSection(accordion,"Data",4);
            controls.GroupCount = matlabx.ui.axes.plot.Demos.numericControl( ...
                dataPane,1,"Groups",3,1,9,1);
            controls.PointCount = matlabx.ui.axes.plot.Demos.numericControl( ...
                dataPane,2,"Points per group",75,5,1000,5);
            controls.ColorDataMode = matlabx.ui.axes.plot.Demos.dropDownControl( ...
                dataPane,3,"Color data",["Group RGB","Scalar"],"Group RGB");
            controls.Generate = uibutton(dataPane,"Text","Generate random data");
            controls.Generate.Layout.Row = 4;
            controls.Generate.Layout.Column = [1 2];
            matlabx.ui.axes.plot.Demos.styleControl(controls.Generate);

            pointsPane = matlabx.ui.axes.plot.Demos.addSection(accordion,"Points",9);
            controls.MarkerMode = matlabx.ui.axes.plot.Demos.dropDownControl( ...
                pointsPane,1,"Marker mode",["single","multi","auto"],"multi");
            controls.MarkerSize = matlabx.ui.axes.plot.Demos.numericControl( ...
                pointsPane,2,"Marker size",40,1,300,1);
            controls.MarkerLineWidth = matlabx.ui.axes.plot.Demos.numericControl( ...
                pointsPane,3,"Line width",0.5,0.1,10,0.1);
            controls.MarkerFaceAlpha = matlabx.ui.axes.plot.Demos.numericControl( ...
                pointsPane,4,"Face alpha",0.65,0,1,0.05);
            controls.MarkerFaceColorMode = matlabx.ui.axes.plot.Demos.dropDownControl( ...
                pointsPane,5,"Face color",["CData","auto","Custom"],"CData");
            controls.MarkerFaceColor = matlabx.ui.axes.plot.Demos.colorControl( ...
                pointsPane,6,"Custom face",[0 0.4470 0.7410]);
            controls.MarkerEdgeAlpha = matlabx.ui.axes.plot.Demos.numericControl( ...
                pointsPane,7,"Edge alpha",0.8,0,1,0.05);
            controls.MarkerEdgeMode = matlabx.ui.axes.plot.Demos.dropDownControl( ...
                pointsPane,8,"Edge color",["CData","auto","Custom"],"auto");

            controls.MarkerEdgeColor = matlabx.ui.axes.plot.Demos.colorControl( ...
                pointsPane,9,"Custom edge",[0 0 0]);

            hullPane = matlabx.ui.axes.plot.Demos.addSection(accordion,"Hulls",9);
            controls.HullVisible = matlabx.ui.axes.plot.Demos.checkBoxControl( ...
                hullPane,1,"Visible",true);
            controls.HullType = matlabx.ui.axes.plot.Demos.dropDownControl( ...
                hullPane,2,"Type",["concave","convex"],"concave");
            controls.HullLineWidth = matlabx.ui.axes.plot.Demos.numericControl( ...
                hullPane,3,"Line width",1,0.1,10,0.1);
            controls.HullFaceAlpha = matlabx.ui.axes.plot.Demos.numericControl( ...
                hullPane,4,"Face alpha",0.2,0,1,0.05);
            controls.HullEdgeAlpha = matlabx.ui.axes.plot.Demos.numericControl( ...
                hullPane,5,"Edge alpha",0.9,0,1,0.05);
            controls.HullFaceColorMode = matlabx.ui.axes.plot.Demos.dropDownControl( ...
                hullPane,6,"Face color",["auto","Custom"],"auto");
            controls.HullFaceColor = matlabx.ui.axes.plot.Demos.colorControl( ...
                hullPane,7,"Custom face",[0.3 0.6 0.9]);
            controls.HullEdgeColorMode = matlabx.ui.axes.plot.Demos.dropDownControl( ...
                hullPane,8,"Edge color",["auto","Custom"],"auto");
            controls.HullEdgeColor = matlabx.ui.axes.plot.Demos.colorControl( ...
                hullPane,9,"Custom edge",[0 0 0]);

            axesPane = matlabx.ui.axes.plot.Demos.addSection(accordion,"Axes",6);
            controls.Title = matlabx.ui.axes.plot.Demos.textControl( ...
                axesPane,1,"Title","Random clusters");
            controls.XLabel = matlabx.ui.axes.plot.Demos.textControl( ...
                axesPane,2,"X label","X");
            controls.YLabel = matlabx.ui.axes.plot.Demos.textControl( ...
                axesPane,3,"Y label","Y");
            controls.LegendVisible = matlabx.ui.axes.plot.Demos.checkBoxControl( ...
                axesPane,4,"Legend",true);
            controls.BackgroundColor = matlabx.ui.axes.plot.Demos.colorControl( ...
                axesPane,5,"Background",[1 1 1]);
            controls.ForegroundColor = matlabx.ui.axes.plot.Demos.colorControl( ...
                axesPane,6,"Foreground",[0 0 0]);

            colorPane = matlabx.ui.axes.plot.Demos.addSection(accordion,"Color mapping",3);
            controls.Colormap = matlabx.ui.axes.plot.Demos.dropDownControl( ...
                colorPane,1,"Colormap",["parula","turbo","hot","cool","gray"],"parula");
            controls.CLimLow = matlabx.ui.axes.plot.Demos.numericControl( ...
                colorPane,2,"Color limit min",0,-100,100,0.05);
            controls.CLimHigh = matlabx.ui.axes.plot.Demos.numericControl( ...
                colorPane,3,"Color limit max",1,-100,100,0.05);

            controls.Generate.ButtonPushedFcn = @(~,~) ...
                matlabx.ui.axes.plot.Demos.generateScatter(renderer,controls);
            matlabx.ui.axes.plot.Demos.assignStyleCallbacks(controls, ...
                @() matlabx.ui.axes.plot.Demos.applyScatterStyle(renderer,controls), ...
                ["Generate","ColorDataMode"]);
            controls.ColorDataMode.ValueChangedFcn = @(~,~) ...
                matlabx.ui.axes.plot.Demos.generateScatter(renderer,controls);
            accordion.getItem("Data").expand();
            accordion.getItem("Points").expand();
            matlabx.ui.axes.plot.Demos.generateScatter(renderer,controls);
            matlabx.ui.axes.plot.Demos.applyScatterStyle(renderer,controls);
            movegui(fig,"center");
            fig.Visible = "on";
        end

        function [fig,host,renderer] = violin()
        %VIOLIN Open an interactive ViolinRenderer demonstration.
            [fig,accordion,host] = matlabx.ui.axes.plot.Demos.createShell( ...
                "Violin demo");
            renderer = matlabx.ui.axes.plot.ViolinRenderer;
            host.mount(renderer);

            dataPane = matlabx.ui.axes.plot.Demos.addSection(accordion,"Data",3);
            controls.GroupCount = matlabx.ui.axes.plot.Demos.numericControl( ...
                dataPane,1,"Groups",4,1,9,1);
            controls.SampleCount = matlabx.ui.axes.plot.Demos.numericControl( ...
                dataPane,2,"Samples per group",100,5,1000,5);
            controls.Generate = uibutton(dataPane,"Text","Generate random data");
            controls.Generate.Layout.Row = 3;
            controls.Generate.Layout.Column = [1 2];
            matlabx.ui.axes.plot.Demos.styleControl(controls.Generate);

            pointsPane = matlabx.ui.axes.plot.Demos.addSection(accordion,"Points",10);
            controls.PointsVisible = matlabx.ui.axes.plot.Demos.checkBoxControl( ...
                pointsPane,1,"Visible",true);
            controls.MarkerSize = matlabx.ui.axes.plot.Demos.numericControl( ...
                pointsPane,2,"Marker size",24,1,300,1);
            controls.MarkerLineWidth = matlabx.ui.axes.plot.Demos.numericControl( ...
                pointsPane,3,"Line width",0.5,0.1,10,0.1);
            controls.MarkerFaceAlpha = matlabx.ui.axes.plot.Demos.numericControl( ...
                pointsPane,4,"Face alpha",0.5,0,1,0.05);
            controls.MarkerEdgeAlpha = matlabx.ui.axes.plot.Demos.numericControl( ...
                pointsPane,5,"Edge alpha",1,0,1,0.05);
            controls.MarkerFaceColorMode = matlabx.ui.axes.plot.Demos.dropDownControl( ...
                pointsPane,6,"Face color",["CData","auto","Custom"],"CData");
            controls.MarkerFaceColor = matlabx.ui.axes.plot.Demos.colorControl( ...
                pointsPane,7,"Custom face",[0 0.4470 0.7410]);
            controls.MarkerEdgeColorMode = matlabx.ui.axes.plot.Demos.dropDownControl( ...
                pointsPane,8,"Edge color",["CData","auto","Custom"],"Custom");
            controls.MarkerEdgeColor = matlabx.ui.axes.plot.Demos.colorControl( ...
                pointsPane,9,"Custom edge",[0 0 0]);
            controls.XJitterWidth = matlabx.ui.axes.plot.Demos.numericControl( ...
                pointsPane,10,"Jitter width",0.6,0.05,1,0.05);

            violinPane = matlabx.ui.axes.plot.Demos.addSection(accordion,"Violins",7);
            controls.ViolinsVisible = matlabx.ui.axes.plot.Demos.checkBoxControl( ...
                violinPane,1,"Visible",true);
            controls.ViolinFaceMode = matlabx.ui.axes.plot.Demos.dropDownControl( ...
                violinPane,2,"Face color",["auto","Custom"],"auto");
            controls.ViolinFaceColor = matlabx.ui.axes.plot.Demos.colorControl( ...
                violinPane,3,"Custom face",[0.3 0.6 0.9]);
            controls.ViolinEdgeMode = matlabx.ui.axes.plot.Demos.dropDownControl( ...
                violinPane,4,"Edge color",["auto","Custom"],"auto");
            controls.ViolinEdgeColor = matlabx.ui.axes.plot.Demos.colorControl( ...
                violinPane,5,"Custom edge",[0 0 0]);
            controls.ViolinEdgeAlpha = matlabx.ui.axes.plot.Demos.numericControl( ...
                violinPane,6,"Edge alpha",1,0,1,0.05);
            controls.ViolinLineWidth = matlabx.ui.axes.plot.Demos.numericControl( ...
                violinPane,7,"Line width",1,0.1,10,0.1);

            summaryPane = matlabx.ui.axes.plot.Demos.addSection(accordion,"Summary",7);
            controls.ErrorBarsVisible = matlabx.ui.axes.plot.Demos.checkBoxControl( ...
                summaryPane,1,"Visible",true);
            controls.CentralStatistic = matlabx.ui.axes.plot.Demos.dropDownControl( ...
                summaryPane,2,"Center",["mean","median"],"mean");
            controls.ErrorStatistic = matlabx.ui.axes.plot.Demos.dropDownControl( ...
                summaryPane,3,"Interval",["std","sem","iqr"],"std");
            controls.ErrorBarsColorMode = matlabx.ui.axes.plot.Demos.dropDownControl( ...
                summaryPane,4,"Color",["auto","Custom"],"Custom");
            controls.ErrorBarsColor = matlabx.ui.axes.plot.Demos.colorControl( ...
                summaryPane,5,"Custom color",[0 0 0]);
            controls.ErrorBarsLineWidth = matlabx.ui.axes.plot.Demos.numericControl( ...
                summaryPane,6,"Error line width",1,0.1,10,0.1);
            controls.CentralStatLineWidth = matlabx.ui.axes.plot.Demos.numericControl( ...
                summaryPane,7,"Center line width",1,0.1,10,0.1);

            axesPane = matlabx.ui.axes.plot.Demos.addSection(accordion,"Axes",5);
            controls.Title = matlabx.ui.axes.plot.Demos.textControl( ...
                axesPane,1,"Title","Random distributions");
            controls.XLabel = matlabx.ui.axes.plot.Demos.textControl( ...
                axesPane,2,"X label","Group");
            controls.YLabel = matlabx.ui.axes.plot.Demos.textControl( ...
                axesPane,3,"Y label","Value");
            controls.BackgroundColor = matlabx.ui.axes.plot.Demos.colorControl( ...
                axesPane,4,"Background",[1 1 1]);
            controls.ForegroundColor = matlabx.ui.axes.plot.Demos.colorControl( ...
                axesPane,5,"Foreground",[0 0 0]);

            controls.Generate.ButtonPushedFcn = @(~,~) ...
                matlabx.ui.axes.plot.Demos.generateViolin(renderer,controls);
            matlabx.ui.axes.plot.Demos.assignStyleCallbacks(controls, ...
                @() matlabx.ui.axes.plot.Demos.applyViolinStyle(renderer,controls), ...
                "Generate");
            accordion.getItem("Data").expand();
            accordion.getItem("Summary").expand();
            matlabx.ui.axes.plot.Demos.generateViolin(renderer,controls);
            matlabx.ui.axes.plot.Demos.applyViolinStyle(renderer,controls);
            movegui(fig,"center");
            fig.Visible = "on";
        end

    end

    methods (Static, Access=private)

        function [fig,accordion,host] = createShell(title)
        %CREATESHELL Create the shared two-column demo figure.
            fig = uifigure("Visible","off","Name",title, ...
                "Position",[100 100 1180 720],"Color",[.12 .12 .12]);
            grid = uigridlayout(fig,[1 2], ...
                "ColumnWidth",{320,"1x"},"RowHeight",{"1x"}, ...
                "ColumnSpacing",5,"Padding",[5 5 5 5], ...
                "BackgroundColor",[.12 .12 .12]);
            leftPane = uigridlayout(grid,[1 1], ...
                "ColumnWidth",{"1x"},"RowHeight",{'fit'}, ...
                "Padding",0,"Scrollable","on", ...
                "BackgroundColor",[.12 .12 .12]);
            leftPane.Layout.Column = 1;
            accordion = matlabx.ui.container.Accordion(leftPane, ...
                "ItemSpacing",5,"Padding",0,"BorderWidth",0, ...
                "BorderColor",[.18 .18 .18], ...
                "BackgroundColor",[.12 .12 .12]);
            host = matlabx.ui.axes.PlotAxes(grid);
            host.Layout.Column = 2;
        end

        function pane = addSection(accordion,title,rowCount)
        %ADDSECTION Add and configure one settings accordion pane.
            accordion.addItem("Title",title, ...
                "BorderColor",[.49 .49 .49], ...
                "TitleBackgroundColor",[.12 .12 .12], ...
                "HoverTitleBackgroundColor",[.3 .3 .3], ...
                "PaneBackgroundColor",[.18 .18 .18], ...
                "FontColor",[.85 .85 .85], ...
                "BorderWidth",1,"ExpandedBorderWidth",1,"TitlePadding",1);
            pane = accordion.getItem(title).Pane;
            set(pane,"RowHeight",repmat({'fit'},1,rowCount), ...
                "ColumnWidth",{130,"1x"},"RowSpacing",5, ...
                "ColumnSpacing",6,"Padding",[6 6 6 6]);
        end

        function control = numericControl(parent,row,label,value,lower,upper,step)
        %NUMERICCONTROL Add one labeled numeric edit field.
            matlabx.ui.axes.plot.Demos.addLabel(parent,row,label);
            control = uieditfield(parent,"numeric","Value",value, ...
                "Limits",[lower upper],"LowerLimitInclusive","on", ...
                "UpperLimitInclusive","on");
            control.Layout.Row = row;
            control.Layout.Column = 2;
            matlabx.ui.axes.plot.Demos.styleControl(control);
            if isprop(control,"RoundFractionalValues") && step == 1
                control.RoundFractionalValues = "on";
            end
        end

        function control = dropDownControl(parent,row,label,items,value)
        %DROPDOWNCONTROL Add one labeled drop-down control.
            matlabx.ui.axes.plot.Demos.addLabel(parent,row,label);
            control = uidropdown(parent,"Items",cellstr(items),"Value",char(value));
            control.Layout.Row = row;
            control.Layout.Column = 2;
            matlabx.ui.axes.plot.Demos.styleControl(control);
        end

        function control = textControl(parent,row,label,value)
        %TEXTCONTROL Add one labeled text edit field.
            matlabx.ui.axes.plot.Demos.addLabel(parent,row,label);
            control = uieditfield(parent,"text","Value",char(value));
            control.Layout.Row = row;
            control.Layout.Column = 2;
            matlabx.ui.axes.plot.Demos.styleControl(control);
        end

        function control = checkBoxControl(parent,row,label,value)
        %CHECKBOXCONTROL Add one labeled check box.
            matlabx.ui.axes.plot.Demos.addLabel(parent,row,label);
            control = uicheckbox(parent,"Text","","Value",value);
            control.Layout.Row = row;
            control.Layout.Column = 2;
            matlabx.ui.axes.plot.Demos.styleControl(control);
        end

        function control = colorControl(parent,row,label,value)
        %COLORCONTROL Add one labeled RGB color picker.
            matlabx.ui.axes.plot.Demos.addLabel(parent,row,label);
            control = uicolorpicker(parent,"Value",value);
            control.Layout.Row = row;
            control.Layout.Column = 2;
        end

        function addLabel(parent,row,text)
        %ADDLABEL Add a left-column settings label.
            label = uilabel(parent,"Text",text,"FontColor",[.85 .85 .85]);
            label.Layout.Row = row;
            label.Layout.Column = 1;
        end

        function styleControl(control)
        %STYLECONTROL Apply the OOPS dark control palette where supported.
            if isprop(control,"BackgroundColor")
                control.BackgroundColor = [.3 .3 .3];
            end
            if isprop(control,"FontColor")
                control.FontColor = [.9 .9 .9];
            end
        end

        function assignStyleCallbacks(controls,callback,excluded)
        %ASSIGNSTYLECALLBACKS Route supported control changes to one style update.
            names = string(fieldnames(controls));
            names = setdiff(names,excluded,"stable");
            for k = 1:numel(names)
                control = controls.(names(k));
                if isprop(control,"ValueChangedFcn")
                    control.ValueChangedFcn = @(~,~) callback();
                end
            end
        end

        function generateScatter(renderer,controls)
        %GENERATESCATTER Generate clustered data in ScatterData format.
            count = round(controls.GroupCount.Value);
            pointCount = round(controls.PointCount.Value);
            colors = lines(count);
            angles = linspace(0,2*pi,count+1);
            xData = cell(1,count); yData = cell(1,count); cData = cell(1,count);
            for k = 1:count
                center = 3*[cos(angles(k)),sin(angles(k))];
                transform = [1+0.35*rand,0.25*randn;0,0.6+0.5*rand];
                values = randn(pointCount,2)*transform + center;
                xData{k} = values(:,1)';
                yData{k} = values(:,2)';
                if string(controls.ColorDataMode.Value) == "Scalar"
                    cData{k} = rescale(hypot(values(:,1)-center(1), ...
                        values(:,2)-center(2)),0,1)';
                else
                    cData{k} = colors(k,:);
                end
            end
            renderer.setData(matlabx.ui.axes.plot.ScatterData( ...
                XData=xData,YData=yData, ...
                SeriesNames="Group " + (1:count),CData=cData));
        end

        function applyScatterStyle(renderer,controls)
        %APPLYSCATTERSTYLE Build and apply style from scatter controls.
            limits = sort([controls.CLimLow.Value,controls.CLimHigh.Value]);
            if limits(1) == limits(2)
                limits(2) = limits(1)+eps(limits(1));
            end
            renderer.setStyle(matlabx.ui.axes.plot.ScatterStyle( ...
                Title=string(controls.Title.Value), ...
                XLabel=string(controls.XLabel.Value), ...
                YLabel=string(controls.YLabel.Value), ...
                LegendVisible=controls.LegendVisible.Value, ...
                MarkerMode=string(controls.MarkerMode.Value), ...
                MarkerSize=controls.MarkerSize.Value, ...
                MarkerLineWidth=controls.MarkerLineWidth.Value, ...
                MarkerFaceAlpha=controls.MarkerFaceAlpha.Value, ...
                MarkerFaceColorMode=string(controls.MarkerFaceColorMode.Value), ...
                MarkerFaceColor=controls.MarkerFaceColor.Value, ...
                MarkerEdgeAlpha=controls.MarkerEdgeAlpha.Value, ...
                MarkerEdgeColorMode=string(controls.MarkerEdgeMode.Value), ...
                MarkerEdgeColor=controls.MarkerEdgeColor.Value, ...
                HullVisible=controls.HullVisible.Value, ...
                HullType=string(controls.HullType.Value), ...
                HullLineWidth=controls.HullLineWidth.Value, ...
                HullFaceAlpha=controls.HullFaceAlpha.Value, ...
                HullEdgeAlpha=controls.HullEdgeAlpha.Value, ...
                HullFaceColorMode=string(controls.HullFaceColorMode.Value), ...
                HullFaceColor=controls.HullFaceColor.Value, ...
                HullEdgeColorMode=string(controls.HullEdgeColorMode.Value), ...
                HullEdgeColor=controls.HullEdgeColor.Value, ...
                BackgroundColor=controls.BackgroundColor.Value, ...
                ForegroundColor=controls.ForegroundColor.Value, ...
                Colormap=matlabx.ui.axes.plot.Demos.colormapValue( ...
                    string(controls.Colormap.Value)), ...
                CLim=limits));
        end

        function map = colormapValue(name)
        %COLORMAPVALUE Return one supported demo colormap.
            switch name
                case "parula"
                    map = parula(256);
                case "turbo"
                    map = turbo(256);
                case "hot"
                    map = hot(256);
                case "cool"
                    map = cool(256);
                case "gray"
                    map = gray(256);
            end
        end

        function generateViolin(renderer,controls)
        %GENERATEVIOLIN Generate distributions in ViolinData format.
            count = round(controls.GroupCount.Value);
            sampleCount = round(controls.SampleCount.Value);
            colors = lines(count);
            values = cell(1,count); cData = cell(1,count);
            for k = 1:count
                center = 1.25*(k-1);
                scale = 0.7+0.25*mod(k-1,3);
                values{k} = center + scale*randn(1,sampleCount);
                if mod(k,2) == 0
                    values{k} = values{k} + 0.35*(rand(1,sampleCount).^2);
                end
                cData{k} = colors(k,:);
            end
            renderer.setData(matlabx.ui.axes.plot.ViolinData( ...
                Values=values,SeriesNames="Group " + (1:count),CData=cData));
        end

        function applyViolinStyle(renderer,controls)
        %APPLYVIOLINSTYLE Build and apply style from violin controls.
            renderer.setStyle(matlabx.ui.axes.plot.ViolinStyle( ...
                Title=string(controls.Title.Value), ...
                XLabel=string(controls.XLabel.Value), ...
                YLabel=string(controls.YLabel.Value), ...
                MarkerSize=controls.MarkerSize.Value, ...
                MarkerLineWidth=controls.MarkerLineWidth.Value, ...
                MarkerFaceAlpha=controls.MarkerFaceAlpha.Value, ...
                MarkerFaceColorMode=string(controls.MarkerFaceColorMode.Value), ...
                MarkerFaceColor=controls.MarkerFaceColor.Value, ...
                MarkerEdgeAlpha=controls.MarkerEdgeAlpha.Value, ...
                MarkerEdgeColorMode=string(controls.MarkerEdgeColorMode.Value), ...
                MarkerEdgeColor=controls.MarkerEdgeColor.Value, ...
                XJitterWidth=controls.XJitterWidth.Value, ...
                PointsVisible=controls.PointsVisible.Value, ...
                ViolinOutlinesVisible=controls.ViolinsVisible.Value, ...
                ViolinFaceColorMode=string(controls.ViolinFaceMode.Value), ...
                ViolinFaceColor=controls.ViolinFaceColor.Value, ...
                ViolinEdgeColorMode=string(controls.ViolinEdgeMode.Value), ...
                ViolinEdgeColor=controls.ViolinEdgeColor.Value, ...
                ViolinEdgeAlpha=controls.ViolinEdgeAlpha.Value, ...
                ViolinLineWidth=controls.ViolinLineWidth.Value, ...
                ErrorBarsVisible=controls.ErrorBarsVisible.Value, ...
                CentralStatistic=string(controls.CentralStatistic.Value), ...
                ErrorStatistic=string(controls.ErrorStatistic.Value), ...
                ErrorBarsColorMode=string(controls.ErrorBarsColorMode.Value), ...
                ErrorBarsColor=controls.ErrorBarsColor.Value, ...
                ErrorBarsLineWidth=controls.ErrorBarsLineWidth.Value, ...
                CentralStatLineWidth=controls.CentralStatLineWidth.Value, ...
                BackgroundColor=controls.BackgroundColor.Value, ...
                ForegroundColor=controls.ForegroundColor.Value));
        end

    end

end
